import React, { useState, useEffect } from "react";

const WakeUpTracker = () => {
  const today = new Date().toISOString().split("T")[0];
  const [time, setTime] = useState("");

  useEffect(() => {
    const saved = localStorage.getItem("wake_" + today);
    if (saved) setTime(saved);
  }, [today]);

  const saveTime = (e) => {
    const value = e.target.value;
    setTime(value);
    localStorage.setItem("wake_" + today, value);
  };

  return (
    <div style={card}>
      <h3>🌅 Wake-up Tracker</h3>
      <input type="time" value={time} onChange={saveTime} />
      {time && <p>✔ Saved: {time}</p>}
    </div>
  );
};

const card = {
  background: "#fff",
  padding: "16px",
  borderRadius: "12px",
  marginTop: "16px",
  boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
};

export default WakeUpTracker;
